  scene.background.set(0x9ca9a4); scene.fog.color.set(0x9ca9a4); scene.fog.near = 36; scene.fog.far = 110;
  player.x = 0; player.y = 1.7; player.z = 3.7; yaw = 0; pitch = 0;
