function installTriggers() {
  const labTrigger = box(world, 'interact-lab', -11, 1.65, -4.25, 4.2, 3.3, 3, new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }), { castShadow: false }); labTrigger.userData.active = true;
  const shopTrigger = box(world, 'interact-shop', 11, 1.65, -4.25, 4.2, 3.3, 3, new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }), { castShadow: false }); shopTrigger.userData.active = true;
  const shaftTrigger = box(world, 'shaft-trigger', 0, 1.4, -8.1, 3.6, 2.4, 3.3, new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }), { castShadow: false }); shaftTrigger.userData.active = true;
