installTriggers();
const originalSetupTunnel = setupTunnel;
setupTunnel = function () { originalSetupTunnel(); addMineExit(); };

function openPanel(type) {
  panelOpen = true; exitPointer(); $('panel-backdrop').classList.remove('hidden');
  const panel = $('interaction-panel');
  const closeButton = '<button class="panel-close" id="panel-close" aria-label="Close">×</button>';
  if (type === 'lab') {
    panel.innerHTML = `${closeButton}<div class="panel-eyebrow">FIELD LAB  /  R&amp;D</div><h2>BUILD A BETTER<br>WAY DOWN.</h2><p class="panel-description">The strata get harder the deeper you go. Put your finds back into the rig and keep the drill moving.</p>
      <div class="upgrade-row"><div class="upgrade-info"><span class="upgrade-icon">⛏</span><span><b>Rotary Drill</b><small>Faster mining · +1 ore value</small></span></div><button class="buy-button" id="upgrade-drill" ${cash < drillCost() ? 'disabled' : ''}>UPGRADE · ${drillCost()} cr</button></div>
      <div class="upgrade-row"><div class="upgrade-info"><span class="upgrade-icon">◉</span><span><b>Oil Reservoir</b><small>Larger tank · +30 L capacity</small></span></div><button class="buy-button" id="upgrade-tank" ${cash < tankCost() || tankLevel >= 4 ? 'disabled' : ''}>${tankLevel >= 4 ? 'MAX LEVEL' : `UPGRADE · ${tankCost()} cr`}</button></div>
      <div class="panel-footer"><span>AVAILABLE CREDITS</span><b>${cash} cr</b></div>`;
    $('panel-close').onclick = closePanel;
    $('upgrade-drill').onclick = () => { if (cash >= drillCost()) { cash -= drillCost(); drillLevel++; updateLayerUI(); popToast(`ROTARY DRILL UPGRADED · LEVEL ${drillLevel}`); openPanel('lab'); } };
    $('upgrade-tank').onclick = () => { if (cash >= tankCost() && tankLevel < 4) { cash -= tankCost(); tankLevel++; fuel = Math.min(maxFuel(), fuel + 30); updateLayerUI(); popToast('OIL RESERVOIR EXPANDED · +30 L'); openPanel('lab'); } };
  } else if (type === 'shop') {
    panel.innerHTML = `${closeButton}<div class="panel-eyebrow">SUPPLY DEPOT  /  FUEL &amp; PROVISIONS</div><h2>KEEP THE<br>DRILL FED.</h2><p class="panel-description">Everything stops when the oil runs out. Refuel here before heading back underground.</p>
      <div class="shop-item"><div class="upgrade-info"><span class="upgrade-icon">⌁</span><span><b>Drill Oil · 20 L</b><small>${fuel >= maxFuel() ? 'Tank full. Make room first.' : `${maxFuel() - fuel} L free in your reservoir`}</small></span></div><button class="buy-button" id="buy-oil" ${cash < 25 || fuel >= maxFuel() ? 'disabled' : ''}>BUY · 25 cr</button></div>
      <div class="shop-item"><div class="upgrade-info"><span class="upgrade-icon">＋</span><span><b>Emergency Ration</b><small>Clear the dust. Back to work.</small></span></div><button class="buy-button" id="buy-snack" ${cash < 10 ? 'disabled' : ''}>BUY · 10 cr</button></div>
      <div class="panel-footer"><span>DRILL OIL / CREDITS</span><b>${fuel} L&nbsp; / &nbsp;${cash} cr</b></div>`;
    $('panel-close').onclick = closePanel;
    $('buy-oil').onclick = () => { if (cash >= 25 && fuel < maxFuel()) { cash -= 25; fuel = Math.min(maxFuel(), fuel + 20); updateLayerUI(); popToast('20 L DRILL OIL ADDED'); openPanel('shop'); } };
    $('buy-snack').onclick = () => { if (cash >= 10) { cash -= 10; updateLayerUI(); popToast('RATION PACKED · YOU GOT THIS'); openPanel('shop'); } };
  } else {
    panel.innerHTML = `${closeButton}<div class="panel-eyebrow">EARTH'S INNER CORE  /  6,371 M</div><h2>YOU MADE IT<br>ALL THE WAY DOWN.</h2><p class="panel-description">The surface is a distant memory. The drill is quiet. You found the center of the Earth — and left your mark on it.</p><div class="lift-stats"><div><small>DEPTH REACHED</small><b>6,371 m</b></div><div><small>ORE RECOVERED</small><b>${oreCount} finds</b></div><div><small>RIG LEVEL</small><b>DRILL · ${drillLevel}</b></div><div><small>FIELD CREDITS</small><b>${cash} cr</b></div></div><button class="buy-button" id="core-return" style="width:100%;padding:14px">RETURN TO CAMP · KEEP EXPLORING</button>`;
    $('panel-close').onclick = closePanel;
    $('core-return').onclick = () => { depth = 0; layerIndex = 0; layerHits = 0; rebuildMine(); returnToSurface(); closePanel(); popToast('WELCOME BACK, PIONEER'); };
