}
function drillCost() { return 80 * drillLevel; }
function tankCost() { return 65 * tankLevel; }
function maxFuel() { return 36 + (tankLevel - 1) * 30; }
function closePanel() { panelOpen = false; $('panel-backdrop').classList.add('hidden'); if (started && !paused) requestLock(); }
function requestLock() { if (started && !panelOpen && !paused && document.pointerLockElement !== canvas) canvas.requestPointerLock?.(); }
function exitPointer() { if (document.pointerLockElement) document.exitPointerLock(); }
function startGame() {
  if (started) return;
  started = true; $('welcome').classList.add('hidden'); $('hud').classList.remove('hidden');
  updateLayerUI(); requestLock(); popToast('FIELD OPERATION ACTIVE · FIND THE SHAFT');
}
$('start-button').addEventListener('click', startGame);
$('sound-button').addEventListener('click', () => { soundOn = !soundOn; $('sound-button').style.opacity = soundOn ? '1' : '.45'; $('sound-button').textContent = soundOn ? '♪' : '×'; });
$('resume-button').addEventListener('click', () => { paused = false; $('pause-screen').classList.add('hidden'); requestLock(); });
canvas.addEventListener('click', () => { if (!started) return; if (inMine && currentTarget?.name === 'mineable' && !panelOpen) mineRock(currentTarget); else if (!pointerLocked && !panelOpen && !paused) requestLock(); });
document.addEventListener('pointerlockchange', () => { pointerLocked = document.pointerLockElement === canvas; });
document.addEventListener('mousemove', e => {
  if (!pointerLocked || panelOpen || paused) return;
  yaw -= e.movementX * .0024; pitch -= e.movementY * .0024; pitch = THREE.MathUtils.clamp(pitch, -1.35, 1.35);
  camera.rotation.order = 'YXZ'; camera.rotation.set(pitch, yaw, 0);
});
document.addEventListener('keydown', e => {
  if (['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)) e.preventDefault();
  if (e.repeat && ['KeyE','Escape','KeyR','Space'].includes(e.code)) return;
  keys.add(e.code);
  if (e.code === 'KeyE' || e.code === 'Space') { if (inMine && currentTarget?.name === 'mineable') mineRock(currentTarget); else interact(); }
  if (e.code === 'KeyR' && started) returnToSurface();
  if (e.code === 'Escape' && started && !panelOpen) { paused = !paused; $('pause-screen').classList.toggle('hidden', !paused); if (paused) exitPointer(); else requestLock(); }
});
document.addEventListener('keyup', e => keys.delete(e.code));
document.addEventListener('pointerlockerror', () => { /* Click-to-mine and keyboard interaction remain available. */ });

// Soft, non-capturing first-person camera on the surface; underground uses free look.
function updateMovement(dt) {
  if (!started || panelOpen || paused) return;
  const speed = inMine ? 3.4 : 4.6;
  let forward = (keys.has('KeyW') || keys.has('ArrowUp') ? 1 : 0) - (keys.has('KeyS') || keys.has('ArrowDown') ? 1 : 0);
  let strafe = (keys.has('KeyD') || keys.has('ArrowRight') ? 1 : 0) - (keys.has('KeyA') || keys.has('ArrowLeft') ? 1 : 0);
  const length = Math.hypot(forward, strafe) || 1; forward /= length; strafe /= length;
  const sin = Math.sin(yaw), cos = Math.cos(yaw);
  const targetVx = (strafe * cos + forward * sin) * speed;
  const targetVz = (strafe * sin - forward * cos) * speed;
  const blend = Math.min(1, dt * 8);
  player.vx += (targetVx - player.vx) * blend; player.vz += (targetVz - player.vz) * blend;
  player.x += player.vx * dt; player.z += player.vz * dt;
  if (inMine) {
    player.x = THREE.MathUtils.clamp(player.x, -5.7, 5.7); player.z = THREE.MathUtils.clamp(player.z, -7, 5.1);
    // Prevent walking through the ore face.
    if (player.z < -10.5) player.z = -10.5;
  } else {
    player.x = THREE.MathUtils.clamp(player.x, -35, 35); player.z = THREE.MathUtils.clamp(player.z, -32, 32);
  }
  const bob = Math.hypot(player.vx, player.vz) > .3 ? Math.sin(clock.elapsedTime * 10) * .035 : 0;
  camera.position.set(player.x, player.y + bob, player.z); camera.rotation.order = 'YXZ'; camera.rotation.set(pitch, yaw, 0);
}
function update(dt) {
  mineCooldown = Math.max(0, mineCooldown - dt);
  toastTimer -= dt; if (toastTimer <= 0) $('toast').classList.remove('show');
  updateMovement(dt); targetUpdate();
  // Gentle moving sun flecks and wind-like drifting particles.
  for (const p of dust) { p.position.y += dt * p.userData.speed; if (p.position.y > 7) p.position.y = .3; }
  renderer.render(scene, camera);
}
function animate() { requestAnimationFrame(animate); update(Math.min(clock.getDelta(), .05)); }

const seedDust = random(782);
for (let i = 0; i < 35; i++) {
  const particle = new THREE.Mesh(new THREE.SphereGeometry(.025 + seedDust() * .025, 5, 4), new THREE.MeshBasicMaterial({ color: 0xe7d2a8, transparent: true, opacity: .25 + seedDust() * .3 }));
  particle.position.set((seedDust() - .5) * 16, seedDust() * 7, (seedDust() - .5) * 18);
  particle.userData.speed = .12 + seedDust() * .2; world.add(particle); dust.push(particle);
}

makeRockCluster(); mines.visible = false; world.visible = true;
camera.position.set(0, 1.7, 5.3); camera.rotation.order = 'YXZ';
window.addEventListener('resize', () => { camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix(); renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8)); });
animate();

