import * as THREE from 'three';
import './style.css';

const $ = (id) => document.getElementById(id);
const canvas = $('scene');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9ca9a4);
scene.fog = new THREE.Fog(0x9ca9a4, 36, 110);
const camera = new THREE.PerspectiveCamera(67, innerWidth / innerHeight, 0.1, 260);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.8));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;

scene.add(new THREE.HemisphereLight(0xc4d2d0, 0x3e3128, 2.1));
const sun = new THREE.DirectionalLight(0xffe6c6, 3.2);
sun.position.set(-18, 30, 12); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -35; sun.shadow.camera.right = 35; sun.shadow.camera.top = 35; sun.shadow.camera.bottom = -35;
scene.add(sun);
const warmFill = new THREE.PointLight(0xe98b50, 28, 22); warmFill.position.set(0, 4, -7); scene.add(warmFill);
const coolFill = new THREE.PointLight(0x79a69d, 25, 30); coolFill.position.set(0, 1, -22); scene.add(coolFill);

const mat = (color, roughness = .86, extra = {}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const mats = {
  earth: mat(0x4c4339), grass: mat(0x626653), concrete: mat(0x77786c), dark: mat(0x202827), metal: mat(0x4c5a57, .47, { metalness: .55 }),
  orange: mat(0xd67b45, .55), yellow: mat(0xd5a64d), green: mat(0x75875c), pale: mat(0xd7d0bc), glass: mat(0x698681, .2, { metalness: .15, emissive: 0x152a27 }),
  dirt: mat(0x70604a), stone: mat(0x686a63), copper: mat(0x956749, .58, { metalness: .3 }), silver: mat(0x8c9995, .42, { metalness: .5 }), crystal: mat(0x709a9a, .26, { metalness: .18, emissive: 0x183a38 }), gold: mat(0xb89c62, .32, { metalness: .42, emissive: 0x34240c }), magma: mat(0xe97043, .32, { emissive: 0x9c3010, emissiveIntensity: 1.7 })
};
const cubeGeo = new THREE.BoxGeometry(1, 1, 1);
function box(parent, name, x, y, z, sx, sy, sz, material, options = {}) {
  const mesh = new THREE.Mesh(options.geometry || cubeGeo, material);
  mesh.name = name; mesh.position.set(x, y, z); mesh.scale.set(sx, sy, sz);
  mesh.castShadow = options.castShadow !== false; mesh.receiveShadow = options.receiveShadow !== false;
  parent.add(mesh); return mesh;
}
function cylinder(parent, name, x, y, z, radiusTop, radiusBottom, height, material, sides = 12) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, sides), material);
  mesh.name = name; mesh.position.set(x, y, z); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function labelTexture(lines, bg = '#202a27', fg = '#f2ead8') {
  const c = document.createElement('canvas'); c.width = 512; c.height = 160;
  const ctx = c.getContext('2d'); ctx.fillStyle = bg; ctx.fillRect(0, 0, c.width, c.height);
  ctx.fillStyle = '#e89252'; ctx.fillRect(0, 0, 12, c.height);
  ctx.fillStyle = fg; ctx.font = '600 45px Arial'; ctx.fillText(lines[0], 38, 67);
  ctx.fillStyle = '#bac0b5'; ctx.font = '20px monospace'; ctx.fillText(lines[1] || '', 40, 112);
  const texture = new THREE.CanvasTexture(c); texture.colorSpace = THREE.SRGBColorSpace;
  return new THREE.MeshStandardMaterial({ map: texture, roughness: .8 });
}
function random(seed) { let t = seed >>> 0; return () => { t += 0x6D2B79F5; let x = t; x = Math.imul(x ^ x >>> 15, x | 1); x ^= x + Math.imul(x ^ x >>> 7, x | 61); return ((x ^ x >>> 14) >>> 0) / 4294967296; }; }

const world = new THREE.Group(); scene.add(world);
const mines = new THREE.Group(); scene.add(mines);
const effects = new THREE.Group(); scene.add(effects);
let rocks = [], dust = [], started = false, inMine = false, pointerLocked = false, panelOpen = false, paused = false;
let depth = 0, cash = 180, fuel = 36, drillLevel = 1, tankLevel = 1, oreCount = 0, layerHits = 0;
let layerIndex = 0, yaw = 0, pitch = 0, currentTarget = null, mineCooldown = 0, toastTimer = 0, soundOn = true;
const clock = new THREE.Clock();
const raycaster = new THREE.Raycaster(); raycaster.far = 18;
const keys = new Set();
const player = { x: 0, y: 1.7, z: 5.3, vx: 0, vz: 0 };

function buildSurface() {
  box(world, 'ground', 0, -.38, 0, 90, .75, 90, mats.earth, { castShadow: false });
  const rand = random(4281);
  for (let i = 0; i < 170; i++) {
    const x = (rand() - .5) * 70, z = (rand() - .5) * 70;
    if (Math.abs(x) < 15 && z > -18 && z < 12) continue;
    const r = .1 + rand() * .36;
    const pebble = box(world, 'gravel', x, .03, z, r * 2.5, .08 + rand() * .1, r * 1.8, i % 3 ? mats.stone : mats.concrete, { castShadow: false });
    pebble.rotation.y = rand() * 3;
  }
  for (let i = 0; i < 16; i++) {
    const x = (rand() - .5) * 72, z = (rand() - .5) * 70;
    if (Math.abs(x) < 17 && z > -19 && z < 14) continue;
    const height = .45 + rand() * 1.4;
    const tuft = cylinder(world, 'scrub', x, height * .48, z, .03, .15 + rand() * .12, height, i % 2 ? mats.green : mats.dirt, 5);
    tuft.rotation.z = (rand() - .5) * .2;
  }
  box(world, 'lift apron', 0, .055, -7.2, 8.4, .14, 8.6, mats.concrete);
  for (const x of [-4.25, 4.25]) box(world, 'apron stripe', x, .14, -7.2, .12, .02, 8.7, mats.yellow, { castShadow: false });
  box(world, 'shaft mouth', 0, .19, -8.15, 5.2, .08, 5.2, mats.dark, { castShadow: false });
  for (const [x, z, sx, sz] of [[0, -10.8, 5.8, .36], [0, -5.5, 5.8, .36], [-2.7, -8.15, .36, 5.7], [2.7, -8.15, .36, 5.7]]) box(world, 'lift rim', x, .25, z, sx, .42, sz, mats.metal);
  for (const x of [-3.6, 3.6]) {
    box(world, 'headframe leg', x, 4, -8.1, .34, 7.5, .38, mats.orange);
    const brace = box(world, 'headframe brace', x * .73, 4.1, -8.1, .18, 6.9, .18, mats.yellow); brace.rotation.z = x > 0 ? -.38 : .38;
    box(world, 'leg foot', x, .5, -8.1, 1.15, .42, 1.25, mats.dark);
  }
  box(world, 'headframe cap', 0, 7.65, -8.1, 8.2, .48, .65, mats.orange);
  box(world, 'headframe crossbar', 0, 6.8, -8.1, 6.3, .18, .2, mats.yellow);
  cylinder(world, 'hoist drum', 0, 6.55, -8.08, .68, .68, 1.45, mats.metal, 18).rotation.z = Math.PI / 2;
  for (let i = 0; i < 5; i++) box(world, 'cable', -.65 + i * .32, 3.65, -8.05, .035, 5.25, .035, mats.dark, { castShadow: false });
  box(world, 'lift cabin', 0, 1.4, -8.15, 2.4, .2, 2.45, mats.yellow);
  box(world, 'lift panel', 1.58, 1.15, -7.25, .32, .78, .12, mats.dark);
  const indicator = new THREE.PointLight(0x9dc882, 3, 5); indicator.position.set(1.7, 1.55, -7.15); world.add(indicator);
  buildFacility(-11, 0, 'lab'); buildFacility(11, 0, 'shop');
  for (const [x, z] of [[-5, -2], [5, -2], [-5, 3], [5, 3]]) {
    cylinder(world, 'lamp post', x, 2.1, z, .055, .075, 4.1, mats.dark, 8);
    box(world, 'lamp hood', x, 4.15, z, .52, .13, .52, mats.yellow);
    const lamp = new THREE.PointLight(0xffbb78, 4, 9); lamp.position.set(x, 3.9, z); world.add(lamp);
  }
  const cart = new THREE.Group(); cart.position.set(5.4, .05, -11.2); world.add(cart);
  box(cart, 'cart chassis', 0, .72, 0, 2.8, .75, 3.1, mats.orange);
  box(cart, 'cart cabin', -.15, 1.55, .25, 1.5, 1.1, 1.45, mats.dark);
  box(cart, 'cart window', -.15, 1.58, -.51, 1.18, .58, .08, mats.glass);
  for (const x of [-1.12, 1.12]) for (const z of [-1, 1]) cylinder(cart, 'cart wheel', x, .45, z, .43, .43, .24, mats.dark, 12).rotation.z = Math.PI / 2;
  const arm = box(cart, 'cart mast', 0, 2.6, -1.05, .16, 3.2, .16, mats.metal); arm.rotation.x = -.3;
  const drill = cylinder(cart, 'cart drill', 0, 2.95, -2.1, .13, .28, 2.2, mats.yellow, 8); drill.rotation.x = Math.PI / 2;
  for (const z of [-16, -3, 10]) for (const x of [-18, 18]) {
    cylinder(world, 'survey beacon', x, 1.3, z, .07, .08, 2.6, mats.dark, 8);
    const glow = new THREE.PointLight(0xff985b, 1.2, 6); glow.position.set(x, 2.7, z); world.add(glow);
  }
}
function buildFacility(x, z, kind) {
  const lab = kind === 'lab', g = new THREE.Group(); g.position.set(x, 0, z); world.add(g);
  const width = 8.1, height = lab ? 4.3 : 3.9;
  box(g, `${kind} foundation`, 0, .2, 0, width + .6, .4, 6.5, mats.dark);
  box(g, `${kind} walls`, 0, height / 2 + .4, 0, width, height, 5.9, lab ? mats.concrete : mats.orange);
  box(g, `${kind} roof`, 0, height + .5, 0, width + .5, .36, 6.4, mats.dark);
  box(g, `${kind} fascia`, 0, height + .72, 0, width + .7, .14, 6.55, lab ? mats.green : mats.yellow);
  for (const wx of [-2.55, 2.55]) {
    box(g, 'window frame', wx, 2.25, -3.02, 1.75, 1.75, .12, mats.dark);
    box(g, 'window', wx, 2.25, -3.1, 1.48, 1.48, .06, mats.glass, { castShadow: false });
    box(g, 'window mullion', wx, 2.25, -3.15, .055, 1.48, .04, mats.pale, { castShadow: false });
  }
  box(g, 'door frame', 0, 1.55, -3.02, 1.65, 3.1, .18, mats.dark);
  box(g, 'door', 0, 1.53, -3.14, 1.34, 2.84, .1, mats.metal);
  box(g, 'door glass', 0, 2.1, -3.2, 1.08, 1.45, .05, mats.glass, { castShadow: false });
  box(g, 'door handle', .48, 1.2, -3.28, .06, .35, .08, mats.yellow);
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 1), labelTexture(lab ? ['FIELD LAB', 'RESEARCH  /  UPGRADES'] : ['SUPPLY DEPOT', 'FUEL  /  PROVISIONS']));
  sign.position.set(0, height + .08, -3.34); g.add(sign);
  if (lab) {
    for (const [vx, vz] of [[-2.8, 1.8], [2.7, 1.7]]) {
      box(g, 'lab vent', vx, height + .86, vz, .8, .5, .72, mats.metal);
      for (let i = 0; i < 3; i++) box(g, 'vent slat', vx, height + .84 + i * .11, vz - .38, .82, .035, .08, mats.dark);
    }
    cylinder(g, 'antenna mast', -3.3, height + 1.3, 1.8, .035, .05, 1.8, mats.metal, 8);
    for (let i = 0; i < 3; i++) box(g, 'antenna rung', -3.3, height + .7 + i * .35, 1.8, .6, .035, .04, mats.yellow);
    box(g, 'lab side stripe', 4.08, 2.9, 0, .1, .18, 4.7, mats.green);
  } else {
    for (const [bx, bz] of [[-2.8, 3.8], [0, 4], [2.8, 3.8]]) {
      cylinder(g, 'oil drum', bx, .95, bz, .54, .54, 1.7, mats.dark, 14);
