    box(g, 'pump face', -4.5, 1.56, -1.25, .57, .63, .05, mats.dark);
    box(g, 'pump screen', -4.5, 1.58, -1.29, .41, .32, .03, mats.glass);
    const hose = cylinder(g, 'pump hose', -4.05, 1.13, -.9, .055, .055, 1.65, mats.dark, 8); hose.rotation.z = Math.PI / 2;
  }
  box(g, 'stoop', 0, .24, -3.7, 2.6, .28, 1.15, mats.concrete);
}
buildSurface();

